export const dashboardCss = "/*\n * Dashboard styles \u2014 token values come verbatim from DESIGN.md frontmatter\n * (CSS custom properties are the implementation mapping; DESIGN.md is the SSOT).\n */\n\n:root {\n  /* colors */\n  --color-background-100: #ffffff;\n  --color-background-200: #f5f7fa;\n  --color-background-300: #edf1f6;\n  --color-gray-400: #d5dce5;\n  --color-gray-600: #8995a6;\n  --color-gray-900: #506070;\n  --color-gray-1000: #1c2430;\n  --color-blue-700: #1756b8;\n  --color-blue-800: #12458f;\n  --color-blue-100: #eaf1ff;\n  --color-red-700: #b42318;\n  --color-red-100: #fff0ed;\n  --color-amber-700: #a35300;\n  --color-amber-100: #fff5e5;\n  --color-green-700: #147d48;\n  --color-green-100: #eaf8ef;\n  --color-purple-700: #7042a0;\n\n  /* spacing (8px rhythm; 8 inside groups, 16 between groups, 32 between sections) */\n  --space-1: 4px;\n  --space-2: 8px;\n  --space-3: 12px;\n  --space-4: 16px;\n  --space-6: 24px;\n  --space-8: 32px;\n\n  /* rounded */\n  --rounded-sm: 6px;\n\n  /* typography families */\n  --font-sans: system-ui, -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif;\n  --font-mono: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;\n}\n\n* {\n  box-sizing: border-box;\n}\n\nhtml,\nbody {\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  background: var(--color-background-200);\n  color: var(--color-gray-1000);\n  font-family: var(--font-sans);\n  font-size: 16px;\n  line-height: 1.6;\n  min-height: 100vh;\n  display: flex;\n  flex-direction: column;\n}\n\n#app {\n  display: flex;\n  flex-direction: column;\n  min-height: 100vh;\n}\n\n.heading-28 {\n  font-size: 28px;\n  font-weight: 600;\n  line-height: 1.25;\n  letter-spacing: -0.02em;\n  margin: 0 0 var(--space-4);\n}\n\n/* Skip link \u2014 visible on focus only */\n.skip-link {\n  position: absolute;\n  left: -9999px;\n  top: 0;\n  background: var(--color-background-100);\n  color: var(--color-blue-700);\n  padding: var(--space-2) var(--space-4);\n  border-radius: var(--rounded-sm);\n  z-index: 10;\n}\n\n.skip-link:focus {\n  left: var(--space-4);\n  top: var(--space-4);\n}\n\n/* Header / navigation */\n.app-header {\n  background: var(--color-background-100);\n  border-bottom: 1px solid var(--color-gray-400);\n}\n\n.app-nav {\n  max-width: 1440px;\n  margin: 0 auto;\n  padding: var(--space-2) var(--space-8);\n  display: flex;\n  align-items: center;\n  gap: var(--space-2);\n  flex-wrap: wrap;\n}\n\n.app-title {\n  font-weight: 600;\n  margin-right: var(--space-4);\n}\n\n.nav-link {\n  display: inline-flex;\n  align-items: center;\n  min-height: 44px;\n  padding: 0 var(--space-4);\n  border-radius: var(--rounded-sm);\n  color: var(--color-gray-1000);\n  text-decoration: none;\n}\n\n.nav-link:hover {\n  background: var(--color-background-200);\n}\n\n.nav-link.is-active {\n  color: var(--color-blue-700);\n  background: var(--color-blue-100);\n  font-weight: 600;\n}\n\n/* Main content */\n.app-main {\n  flex: 1;\n  width: 100%;\n  max-width: 1440px;\n  margin: 0 auto;\n  padding: var(--space-8) var(--space-8);\n}\n\n/* Issues: filters */\n.filters {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: flex-end;\n  gap: var(--space-4);\n  padding: var(--space-4);\n  background: var(--color-background-100);\n  border: 1px solid var(--color-gray-400);\n  border-radius: var(--rounded-sm);\n}\n\n.filter-field {\n  display: flex;\n  flex-direction: column;\n  gap: var(--space-2);\n  min-width: 180px;\n}\n\n.filter-field-wide {\n  flex: 1 1 280px;\n}\n\n.filter-field label {\n  font-size: 14px;\n  font-weight: 600;\n  line-height: 1.4;\n}\n\n.filter-field input,\n.filter-field select {\n  height: 44px;\n  padding: 0 12px;\n  font-family: var(--font-sans);\n  font-size: 16px;\n  line-height: 1.6;\n  color: var(--color-gray-1000);\n  background: var(--color-background-100);\n  border: 1px solid var(--color-gray-600);\n  border-radius: var(--rounded-sm);\n}\n\n.button-secondary {\n  height: 44px;\n  padding: 0 16px;\n  font-family: var(--font-sans);\n  font-size: 14px;\n  font-weight: 600;\n  line-height: 1.4;\n  color: var(--color-gray-1000);\n  background: var(--color-background-100);\n  border: 1px solid var(--color-gray-600);\n  border-radius: var(--rounded-sm);\n  cursor: pointer;\n}\n\n.button-secondary:hover:enabled {\n  background: var(--color-background-200);\n}\n\n.button-secondary:active:enabled {\n  background: var(--color-background-300);\n}\n\n.button-secondary:disabled {\n  color: var(--color-gray-900);\n  background: var(--color-background-300);\n  border-color: var(--color-gray-400);\n  cursor: default;\n}\n\n.hint {\n  margin: var(--space-2) 0 0;\n  color: var(--color-gray-900);\n  font-size: 14px;\n  line-height: 1.5;\n}\n\n/* Issues: list */\n.table-scroll {\n  overflow-x: auto;\n  background: var(--color-background-100);\n  border: 1px solid var(--color-gray-400);\n  border-radius: var(--rounded-sm);\n}\n\n/* Issue list, workflow list, iteration list: one flat data-table pattern. */\n.issue-table,\n.data-table {\n  width: 100%;\n  border-collapse: collapse;\n  font-size: 14px;\n  line-height: 1.5;\n}\n\n.issue-table caption,\n.data-table caption {\n  padding: var(--space-3) var(--space-4);\n  color: var(--color-gray-900);\n  text-align: left;\n}\n\n.issue-table th,\n.issue-table td,\n.data-table th,\n.data-table td {\n  padding: var(--space-3) var(--space-4);\n  border-top: 1px solid var(--color-gray-400);\n  text-align: left;\n  vertical-align: top;\n}\n\n.issue-table thead th,\n.data-table thead th {\n  border-top: none;\n  color: var(--color-gray-900);\n  font-weight: 600;\n}\n\n.issue-table tbody tr:hover,\n.data-table tbody tr:hover {\n  background: var(--color-background-200);\n}\n\n.col-id,\n.col-secondary {\n  white-space: nowrap;\n  font-variant-numeric: tabular-nums;\n}\n\n.col-title {\n  min-width: 240px;\n}\n\n.col-title a {\n  color: var(--color-blue-700);\n}\n\n/* Secondary metadata for narrow screens (shown below the title, never instead of it) */\n.row-meta {\n  display: none;\n}\n\n.mono {\n  font-family: var(--font-mono);\n  font-size: 13px;\n  line-height: 1.6;\n}\n\n.badge {\n  display: inline-block;\n  padding: 2px var(--space-2);\n  border: 1px solid var(--color-gray-600);\n  border-radius: var(--rounded-sm);\n  background: var(--color-background-200);\n  font-size: 14px;\n  line-height: 1.4;\n  color: var(--color-gray-1000);\n}\n\n.badge[data-tone=\"danger\"] {\n  color: var(--color-red-700);\n  background: var(--color-red-100);\n  border-color: var(--color-red-700);\n}\n\n.badge[data-tone=\"success\"] {\n  color: var(--color-green-700);\n  background: var(--color-green-100);\n  border-color: var(--color-green-700);\n}\n\n.badge[data-tone=\"terminal\"] {\n  color: var(--color-purple-700);\n  background: var(--color-background-100);\n  border-color: var(--color-purple-700);\n}\n\n/* Amber for a disclosed data gap: a missing catalog join, pin or execution row. */\n.badge[data-tone=\"warning\"] {\n  color: var(--color-amber-700);\n  background: var(--color-amber-100);\n  border-color: var(--color-amber-700);\n}\n\n/* One row of join-disclosure badges, flush with the content it qualifies. */\n.badges {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--space-2);\n  margin: var(--space-2) 0 0;\n}\n\n.pager {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--space-2);\n  margin-top: var(--space-4);\n}\n\n.pager-summary {\n  margin: 0 var(--space-2);\n  color: var(--color-gray-900);\n  font-size: 14px;\n}\n\n/* States */\n.empty-state {\n  padding: var(--space-8) var(--space-4);\n  background: var(--color-background-100);\n  border: 1px solid var(--color-gray-400);\n  border-radius: var(--rounded-sm);\n}\n\n.notice {\n  margin-top: var(--space-4);\n  padding: var(--space-3) var(--space-4);\n  border: 1px solid var(--color-gray-400);\n  border-radius: var(--rounded-sm);\n  background: var(--color-background-100);\n}\n\n.notice[data-tone=\"error\"] {\n  color: var(--color-red-700);\n  background: var(--color-red-100);\n  border-color: var(--color-red-700);\n}\n\n.notice[data-tone=\"warning\"] {\n  color: var(--color-amber-700);\n  background: var(--color-amber-100);\n  border-color: var(--color-amber-700);\n}\n\n/* One fact per line inside a stale/unavailable disclosure notice. */\n.notice-line {\n  margin: 0;\n  overflow-wrap: anywhere;\n}\n\n.notice-line + .notice-line {\n  margin-top: var(--space-2);\n}\n\n.visually-hidden {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  margin: -1px;\n  padding: 0;\n  border: 0;\n  overflow: hidden;\n  clip-path: inset(50%);\n  white-space: nowrap;\n}\n\n/* Issues: detail */\n.back-link {\n  margin: 0 0 var(--space-4);\n}\n\n.back-link a {\n  color: var(--color-blue-700);\n}\n\n.detail-id {\n  margin: 0 0 var(--space-6);\n  color: var(--color-gray-900);\n}\n\n.detail-section {\n  margin-top: var(--space-8);\n}\n\n.heading-20 {\n  font-size: 20px;\n  font-weight: 600;\n  line-height: 1.4;\n  letter-spacing: -0.01em;\n  margin: 0 0 var(--space-3);\n}\n\n.facts {\n  margin: 0;\n}\n\n.fact {\n  display: grid;\n  grid-template-columns: minmax(120px, 200px) 1fr;\n  gap: var(--space-2) var(--space-4);\n  padding: var(--space-2) 0;\n  border-top: 1px solid var(--color-gray-400);\n}\n\n.fact:first-child {\n  border-top: none;\n}\n\n.fact-label {\n  color: var(--color-gray-900);\n  font-size: 14px;\n  font-weight: 600;\n  line-height: 1.4;\n}\n\n.fact-value {\n  margin: 0;\n  font-size: 16px;\n  line-height: 1.6;\n  overflow-wrap: anywhere;\n}\n\n.prose {\n  margin: 0;\n  font-size: 16px;\n  line-height: 1.6;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.history,\n.relations {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.history-item,\n.relations > li {\n  padding: var(--space-3) 0;\n  border-top: 1px solid var(--color-gray-400);\n}\n\n.history-item:first-child,\n.relations > li:first-child {\n  border-top: none;\n}\n\n.history-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: center;\n  gap: var(--space-2);\n  margin: 0 0 var(--space-2);\n}\n\n.history-kind {\n  font-size: 14px;\n  font-weight: 600;\n  line-height: 1.4;\n}\n\n.history-migration {\n  margin: 0 0 var(--space-2);\n  color: var(--color-gray-900);\n  font-size: 14px;\n  line-height: 1.5;\n  overflow-wrap: anywhere;\n}\n\n.evidence {\n  margin: var(--space-2) 0 0;\n  padding-left: var(--space-4);\n}\n\n/* Roadmap: the milestone board (issue 306)\n   One column per milestone plus the explicit unassigned column. Flat white\n   region with 1px separators, exactly like the dashboard's other data\n   regions: no nested cards, no shadow, no gradient. The wrapper reuses\n   `.table-scroll`, so a board wider than the viewport scrolls inside its own\n   labelled region. Token values come verbatim from DESIGN.md frontmatter. */\n.board {\n  display: grid;\n  grid-auto-flow: column;\n  grid-auto-columns: minmax(220px, 1fr);\n  align-items: start;\n  gap: 0;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.board-column {\n  padding: var(--space-3) var(--space-4);\n  border-left: 1px solid var(--color-gray-400);\n}\n\n.board-column:first-child {\n  border-left: none;\n}\n\n.board-column-head {\n  display: flex;\n  flex-wrap: wrap;\n  align-items: baseline;\n  gap: var(--space-2);\n  margin: 0 0 var(--space-2);\n  padding-bottom: var(--space-2);\n  border-bottom: 1px solid var(--color-gray-400);\n}\n\n.board-column .facts {\n  margin: 0 0 var(--space-2);\n}\n\n.board-column .fact {\n  grid-template-columns: 1fr;\n  gap: var(--space-1);\n  padding: var(--space-1) 0;\n}\n\n.board-column .relations > li {\n  padding: var(--space-2) 0;\n}\n\n/* The unassigned column is named, not a milestone: a muted fill marks it. */\n.board-column-unassigned {\n  background: var(--color-background-200);\n}\n\n.board-counts {\n  margin: 0 0 var(--space-2);\n  padding: 0;\n  list-style: none;\n  color: var(--color-gray-900);\n  font-size: 14px;\n  line-height: 1.5;\n}\n\n.board-count {\n  display: flex;\n  flex-wrap: wrap;\n  justify-content: space-between;\n  gap: var(--space-2);\n  border-top: 1px solid var(--color-gray-400);\n  padding: var(--space-1) 0;\n}\n\n.board-count:first-child {\n  border-top: none;\n}\n\n.board-count-label {\n  overflow-wrap: anywhere;\n}\n\n/* The demoted content authority: closed by default, keyboard-accessible. */\n.collapsible-summary {\n  cursor: pointer;\n}\n\n.collapsible-summary .heading-20 {\n  display: inline;\n  margin: 0;\n}\n\n.collapsible[open] > .collapsible-summary {\n  margin-bottom: var(--space-2);\n}\n\n.legacy-json {\n  margin: var(--space-2) 0 0;\n  padding: var(--space-3);\n  background: var(--color-background-200);\n  border-radius: var(--rounded-sm);\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n}\n\n.external {\n  margin: var(--space-2) 0 0;\n}\n\n.external a {\n  color: var(--color-blue-700);\n  overflow-wrap: anywhere;\n}\n\n/* Issues: issue-flow chart panel (D5) */\n.flow-open {\n  margin: 0 0 var(--space-2);\n  font-size: 16px;\n  line-height: 1.6;\n}\n\n.flow-scroll {\n  margin-top: var(--space-2);\n}\n\n/* Fixed-pixel chart inside a labelled scroll region: below sm the region\n   scrolls horizontally instead of scaling the axis text down (DESIGN.md\n   \"Spacing and responsive layout\"). */\n.flow-figure {\n  margin: 0;\n  padding: var(--space-3) var(--space-4);\n  min-width: 720px;\n}\n\n.flow-chart {\n  display: block;\n}\n\n.flow-line {\n  stroke-width: 2.5;\n  stroke-linecap: round;\n}\n\n.flow-line-captured {\n  stroke: var(--color-blue-700);\n}\n\n.flow-line-retired {\n  stroke: var(--color-purple-700);\n}\n\n.flow-axis {\n  stroke: var(--color-gray-600);\n  stroke-width: 1;\n}\n\n.flow-grid {\n  stroke: var(--color-gray-400);\n  stroke-width: 1;\n  stroke-dasharray: 2 4;\n}\n\n.flow-axis-label {\n  fill: var(--color-gray-900);\n  font-family: var(--font-mono);\n  font-size: 13px;\n  line-height: 1.6;\n}\n\n.flow-legend {\n  display: flex;\n  flex-wrap: wrap;\n  gap: var(--space-2) var(--space-6);\n  padding-top: var(--space-2);\n  border-top: 1px solid var(--color-gray-400);\n  color: var(--color-gray-900);\n  font-size: 14px;\n  line-height: 1.5;\n}\n\n.flow-legend-item {\n  display: inline-flex;\n  align-items: center;\n  gap: var(--space-2);\n}\n\n.flow-legend-item svg {\n  display: block;\n}\n\n.flow-note {\n  margin-top: var(--space-2);\n  max-width: 72ch;\n}\n\n/* Footer */\n.app-footer {\n  background: var(--color-background-100);\n  border-top: 1px solid var(--color-gray-400);\n  color: var(--color-gray-900);\n  font-size: 14px;\n  padding: var(--space-2) var(--space-8);\n}\n\n/* Focus visibility \u2014 never remove */\n:focus-visible {\n  outline: 2px solid var(--color-blue-700);\n  outline-offset: 2px;\n}\n\n/* Responsive: below 768px, side padding drops to 16px */\n@media (max-width: 767px) {\n  .app-nav,\n  .app-main,\n  .app-footer {\n    padding-left: var(--space-4);\n    padding-right: var(--space-4);\n  }\n}\n\n/* Below sm: secondary row metadata moves below the title instead of forcing a\n   page-wide horizontal scroll (DESIGN.md \"Spacing and responsive layout\"). */\n@media (max-width: 479px) {\n  .col-secondary {\n    display: none;\n  }\n\n  .row-meta {\n    display: block;\n    margin-top: var(--space-1);\n    color: var(--color-gray-900);\n    font-size: 14px;\n    line-height: 1.5;\n  }\n\n  .filters {\n    padding: var(--space-3);\n  }\n\n  .fact {\n    grid-template-columns: 1fr;\n    gap: var(--space-1);\n  }\n\n  /* Below sm the board stacks into one column per row instead of forcing a\n     page-wide horizontal scroll (DESIGN.md \"Spacing and responsive layout\"). */\n  .board {\n    grid-auto-flow: row;\n    grid-auto-columns: auto;\n    overflow-x: visible;\n  }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  * {\n    transition: none !important;\n  }\n}\n";
